def audible(critical: bool, muted: bool) -> bool:
    return critical and not muted


class AlertScheduler:
    """Bound mute duration while scheduling repeated critical bench alerts."""

    def __init__(self, interval_s: float, maximum_mute_s: float) -> None:
        if interval_s <= 0 or maximum_mute_s < 0:
            raise ValueError("Invalid alert schedule")
        self.interval_s = interval_s
        self.maximum_mute_s = maximum_mute_s
        self.mute_until = 0.0
        self.last_pulse = None

    def mute(self, now: float, requested_s: float) -> None:
        if now < 0 or requested_s < 0:
            raise ValueError("Invalid mute request")
        self.mute_until = now + min(requested_s, self.maximum_mute_s)

    def tick(self, now: float, critical: bool) -> bool:
        if now < 0 or self.last_pulse is not None and now < self.last_pulse:
            raise ValueError("Invalid alert clock")
        if not audible(critical, now < self.mute_until):
            return False
        due = self.last_pulse is None or now - self.last_pulse >= self.interval_s
        if due:
            self.last_pulse = now
        return due

from dataclasses import dataclass
from enum import IntEnum


def latched(active: bool, acknowledged: bool, unsafe: bool) -> bool:
    return unsafe or (active and not acknowledged)


class Priority(IntEnum):
    ADVISORY = 1
    WARNING = 2
    CRITICAL = 3


@dataclass
class AlarmState:
    code: str
    priority: Priority
    unsafe: bool = False
    active: bool = False
    acknowledged: bool = False


class AlarmRegistry:
    """Keep critical fault latches independent of the operator display.

    Acknowledgement is an event, not proof that the unsafe condition ended.
    """

    def __init__(self) -> None:
        self.alarms: dict[str, AlarmState] = {}
        self.events: list[dict] = []

    def update(self, code: str, priority: Priority, unsafe: bool) -> AlarmState:
        if not code:
            raise ValueError("Alarm code required")
        alarm = self.alarms.setdefault(code, AlarmState(code, priority))
        alarm.priority = priority
        alarm.unsafe = unsafe
        alarm.active = latched(alarm.active, alarm.acknowledged, unsafe)
        if unsafe:
            alarm.acknowledged = False
        self.events.append({"code": code, "unsafe": unsafe, "active": alarm.active})
        return alarm

    def acknowledge(self, code: str) -> bool:
        if code not in self.alarms:
            raise KeyError(code)
        alarm = self.alarms[code]
        alarm.acknowledged = True
        alarm.active = latched(alarm.active, True, alarm.unsafe)
        self.events.append({"code": code, "acknowledged": True, "active": alarm.active})
        return not alarm.active

    def stop_required(self) -> bool:
        return any(a.active and a.priority == Priority.CRITICAL for a in self.alarms.values())

    def visible(self) -> list[AlarmState]:
        return sorted(
            (a for a in self.alarms.values() if a.active), key=lambda a: (-a.priority, a.code)
        )

def highest(alarms: list[dict]) -> dict | None:
    return max(alarms, key=lambda a: a["priority"], default=None)


class PrioritySelector:
    """Keep stable alarm identities and select the highest active priority."""

    def __init__(self) -> None:
        self.events: dict[str, dict] = {}

    def update(self, code: str, priority: int, active: bool) -> None:
        if not code or priority not in (1, 2, 3):
            raise ValueError("Valid alarm code and priority required")
        self.events[code] = {"code": code, "priority": priority, "active": active}

    def select(self) -> dict | None:
        ordered = sorted(self.events.values(), key=lambda e: e["code"])
        selected = highest([e for e in ordered if e["active"]])
        return dict(selected) if selected else None

    def clear_inactive(self) -> None:
        self.events = {code: event for code, event in self.events.items() if event["active"]}

    def snapshot(self) -> list[dict]:
        return [dict(self.events[code]) for code in sorted(self.events)]

    def active_count(self) -> int:
        """Return the retained active-event count for the operator view."""
        return sum(event["active"] for event in self.events.values())

def valid_frame(payload: bytes) -> bool:
    return payload.startswith(b"KIC:") and payload.endswith(b"\n")


class FrameBuffer:
    """Bound retained bytes and expose complete validated synthetic frames."""

    def __init__(self, maximum_bytes: int = 1024) -> None:
        if maximum_bytes < 5:
            raise ValueError("Frame limit too small")
        self.maximum_bytes = maximum_bytes
        self.buffer = bytearray()

    def append(self, chunk: bytes) -> list[bytes]:
        if len(self.buffer) + len(chunk) > self.maximum_bytes:
            self.buffer.clear()
            raise ValueError("Frame exceeds configured limit")
        self.buffer.extend(chunk)
        frames = []
        while b"\n" in self.buffer:
            line, _, remaining = self.buffer.partition(b"\n")
            frame = bytes(line) + b"\n"
            self.buffer = bytearray(remaining)
            if not valid_frame(frame):
                raise ValueError("Invalid message frame")
            frames.append(frame)
        return frames

    def reset(self) -> None:
        """Discard incomplete input after a transport fault."""
        self.buffer.clear()

def overdue(now: float, last: float, timeout: float) -> bool:
    return now - last > timeout


class Heartbeat:
    """Retain the last valid response time and expose deterministic timeout state."""

    def __init__(self, timeout_s: float) -> None:
        if timeout_s <= 0:
            raise ValueError("Positive timeout required")
        self.timeout_s = timeout_s
        self.last_response = None
        self.last_poll = None

    def response(self, now: float) -> None:
        if now < 0 or self.last_response is not None and now < self.last_response:
            raise ValueError("Invalid response timestamp")
        self.last_response = now

    def poll(self, now: float) -> bool:
        if now < 0 or self.last_poll is not None and now < self.last_poll:
            raise ValueError("Invalid polling clock")
        self.last_poll = now
        return self.last_response is None or overdue(now, self.last_response, self.timeout_s)

    def snapshot(self) -> dict:
        return {
            "timeout_s": self.timeout_s,
            "last_response": self.last_response,
            "last_poll": self.last_poll,
        }

import math
from dataclasses import dataclass


def valid_dose(dose: float, minimum: float, maximum: float) -> bool:
    return minimum <= dose <= maximum


@dataclass(frozen=True)
class DrugLimits:
    key: str
    minimum_dose: float
    maximum_dose: float
    concentration: float

    def validate(self) -> None:
        if not self.key or not all(
            math.isfinite(v) for v in (self.minimum_dose, self.maximum_dose, self.concentration)
        ):
            raise ValueError("Invalid drug limits")
        if (
            self.minimum_dose < 0
            or self.maximum_dose < self.minimum_dose
            or self.concentration <= 0
        ):
            raise ValueError("Inconsistent drug limits")


class DoseValidator:
    """Validate library bounds before allowing dose-to-volume conversion."""

    def __init__(self, limits: DrugLimits):
        limits.validate()
        self.limits = limits

    def volume_for(self, dose: float) -> float:
        if not math.isfinite(dose):
            raise ValueError("Invalid dose")
        if not valid_dose(dose, self.limits.minimum_dose, self.limits.maximum_dose):
            raise ValueError("Dose outside validated library bounds")
        return dose / self.limits.concentration

    def check_proposal(self, proposal: dict) -> dict:
        if proposal.get("drug") != self.limits.key:
            raise ValueError("Drug record mismatch")
        if "dose" not in proposal:
            raise ValueError("Dose required")
        return {
            "drug": self.limits.key,
            "dose": proposal["dose"],
            "volume_ml": self.volume_for(proposal["dose"]),
        }

def lookup(library: dict, key: str) -> dict:
    if key not in library:
        raise KeyError(key)
    return dict(library[key])


class DrugLibrary:
    """Copy validated records into an isolated lookup snapshot."""

    def __init__(self, records: dict) -> None:
        self.records: dict[str, dict] = {}
        for key, record in records.items():
            if not key or "minimum" not in record or "maximum" not in record:
                raise ValueError("Incomplete drug record")
            if record["minimum"] < 0 or record["maximum"] < record["minimum"]:
                raise ValueError("Invalid drug bounds")
            self.records[key] = dict(record)

    def get(self, key: str) -> dict:
        return lookup(self.records, key)

    def keys(self) -> list[str]:
        return sorted(self.records)

    def select(self, key: str, dose: float) -> dict:
        record = self.get(key)
        if not record["minimum"] <= dose <= record["maximum"]:
            raise ValueError("Dose outside selected drug limits")
        return {"drug": key, "dose": dose, "limits": record}

import math
from dataclasses import dataclass
from enum import StrEnum


def within_bounds(rate: float, minimum: float, maximum: float) -> bool:
    return minimum <= rate <= maximum


class DeliveryMode(StrEnum):
    STOPPED = "stopped"
    RUNNING = "running"
    PAUSED = "paused"
    FAULT = "fault"


@dataclass(frozen=True)
class DeliveryConfiguration:
    rate_ml_h: float
    target_ml: float
    maximum_rate_ml_h: float

    def validate(self) -> None:
        values = (self.rate_ml_h, self.target_ml, self.maximum_rate_ml_h)
        if not all(math.isfinite(v) for v in values):
            raise ValueError("Non-finite configuration")
        if self.target_ml <= 0 or not within_bounds(self.rate_ml_h, 0.01, self.maximum_rate_ml_h):
            raise ValueError("Delivery configuration outside bounds")


class DeliveryController:
    """Apply validated configuration atomically; inhibit output on any fault."""

    def __init__(self) -> None:
        self.configuration: DeliveryConfiguration | None = None
        self.mode = DeliveryMode.STOPPED
        self.delivered_ml = 0.0
        self.events: list[str] = []

    def configure(self, proposed: DeliveryConfiguration) -> None:
        if self.mode == DeliveryMode.RUNNING:
            raise RuntimeError("Pause before changing configuration")
        proposed.validate()
        self.configuration = proposed
        self.events.append("configuration accepted")

    def start(self, sensor_safe: bool, alarm_active: bool) -> None:
        if self.configuration is None:
            raise RuntimeError("Validated configuration required")
        self.configuration.validate()
        if not sensor_safe or alarm_active:
            self.mode = DeliveryMode.FAULT
            self.events.append("start inhibited")
            return
        self.mode = DeliveryMode.RUNNING
        self.events.append("delivery started")

    def tick(self, elapsed_s: float, sensor_safe: bool) -> float:
        if elapsed_s < 0 or not math.isfinite(elapsed_s):
            self.mode = DeliveryMode.FAULT
            raise ValueError("Invalid elapsed time")
        if not sensor_safe:
            self.mode = DeliveryMode.FAULT
        if self.mode != DeliveryMode.RUNNING or self.configuration is None:
            return 0.0
        increment = self.configuration.rate_ml_h * elapsed_s / 3600.0
        remaining = max(0.0, self.configuration.target_ml - self.delivered_ml)
        delivered = min(increment, remaining)
        self.delivered_ml += delivered
        if self.delivered_ml >= self.configuration.target_ml:
            self.mode = DeliveryMode.STOPPED
            self.events.append("target reached")
        return delivered

    def pause(self) -> None:
        if self.mode == DeliveryMode.RUNNING:
            self.mode = DeliveryMode.PAUSED
            self.events.append("delivery paused")

    def stop(self) -> None:
        self.mode = DeliveryMode.STOPPED
        self.events.append("delivery stopped")

def pulse_interval(rate: float, pulses_per_ml: int) -> float:
    if rate <= 0 or pulses_per_ml <= 0:
        raise ValueError("Positive rate and calibration required")
    return 3600.0 / (rate * pulses_per_ml)


class MotorSchedule:
    """Compute bounded bench pulse schedules from validated calibration.

    This fixture reports requested pulses; it never drives a physical motor.
    """

    def __init__(self, pulses_per_ml: int) -> None:
        if pulses_per_ml <= 0:
            raise ValueError("Positive calibration required")
        self.pulses_per_ml = pulses_per_ml
        self.rate = 0.0
        self.pending = 0.0

    def configure(self, rate: float) -> None:
        pulse_interval(rate, self.pulses_per_ml)
        self.rate = rate

    def pulses(self, elapsed_s: float, enabled: bool) -> int:
        if elapsed_s < 0:
            raise ValueError("Negative elapsed time")
        if not enabled or self.rate <= 0:
            self.pending = 0.0
            return 0
        self.pending += self.rate * self.pulses_per_ml * elapsed_s / 3600.0
        count = int(self.pending)
        self.pending -= count
        return count

def target_reached(delivered: float, target: float) -> bool:
    return delivered >= target


class VolumeAccumulator:
    """Clamp each increment to remaining target and preserve volume on stop."""

    def __init__(self, target: float) -> None:
        if target <= 0:
            raise ValueError("Positive target required")
        self.target = target
        self.delivered = 0.0
        self.stopped = False

    def add(self, requested: float) -> float:
        if requested < 0:
            raise ValueError("Negative delivery increment")
        if self.stopped:
            return 0.0
        actual = min(requested, max(0.0, self.target - self.delivered))
        self.delivered += actual
        self.stopped = target_reached(self.delivered, self.target)
        return actual

    def stop(self) -> None:
        self.stopped = True

    def snapshot(self) -> dict:
        return {"target": self.target, "delivered": self.delivered, "stopped": self.stopped}

import hashlib


def digest(payload: bytes) -> str:
    return hashlib.sha256(payload).hexdigest()


class IntegrityRecord:
    """Retain an immutable digest and verify subsequently exported bytes."""

    def __init__(self, payload: bytes) -> None:
        if not isinstance(payload, bytes):
            raise TypeError("Binary evidence payload required")
        self.expected = digest(payload)
        self.size = len(payload)

    def verify(self, candidate: bytes) -> bool:
        import hmac

        if not isinstance(candidate, bytes) or len(candidate) != self.size:
            return False
        return hmac.compare_digest(self.expected, digest(candidate))

    def describe(self) -> dict:
        return {"algorithm": "sha256", "size_bytes": self.size, "content_hash": self.expected}

    def require_valid(self, candidate: bytes) -> None:
        if not self.verify(candidate):
            raise ValueError("Evidence integrity mismatch")

import hashlib
import json
from dataclasses import asdict, dataclass


def append_event(events: list[dict], event: dict) -> list[dict]:
    if events and event["time"] < events[-1]["time"]:
        raise ValueError("Decreasing timestamp")
    return [*events, dict(event)]


@dataclass(frozen=True)
class AuditEvent:
    time: float
    code: str
    details: dict


class EventRecorder:
    """Append ordered records and expose a digest for synthetic audit trials."""

    def __init__(self) -> None:
        self.events: list[dict] = []

    def record(self, event: AuditEvent) -> None:
        if not event.code:
            raise ValueError("Event code required")
        encoded = asdict(event)
        self.events = append_event(self.events, encoded)

    def export(self) -> list[dict]:
        return json.loads(json.dumps(self.events))

    def content_digest(self) -> str:
        data = json.dumps(self.events, sort_keys=True, separators=(",", ":")).encode()
        return hashlib.sha256(data).hexdigest()

import math
from dataclasses import dataclass


def air_detected(reading: float, limit: float) -> bool:
    return reading > limit


@dataclass(frozen=True)
class AirDecision:
    stop_output: bool
    alarm_required: bool
    reason: str


class AirMonitor:
    """Treat a disconnected or non-finite air sensor as an unsafe fault."""

    def __init__(self, limit: float):
        if not math.isfinite(limit) or limit < 0:
            raise ValueError("Invalid air sensor limit")
        self.limit = limit
        self.latched = False

    def evaluate(self, reading: float | None, connected: bool = True) -> AirDecision:
        if not connected or reading is None or not math.isfinite(reading) or reading < 0:
            self.latched = True
            return AirDecision(True, True, "Air sensor fault")
        self.latched = self.latched or air_detected(reading, self.limit)
        return AirDecision(
            self.latched, self.latched, "Air latch" if self.latched else "Valid safe sample"
        )

    def acknowledge(self, reading: float, connected: bool = True) -> bool:
        if (
            not connected
            or not math.isfinite(reading)
            or reading < 0
            or air_detected(reading, self.limit)
        ):
            return False
        self.latched = False
        return True

def calibrated(reading: float, offset: float) -> float:
    return reading + offset


class Calibration:
    """Keep an explicit gain and offset; reject invalid service updates."""

    def __init__(self, gain: float = 1.0, offset: float = 0.0) -> None:
        import math

        if not math.isfinite(gain) or gain <= 0 or not math.isfinite(offset):
            raise ValueError("Invalid calibration")
        self.gain = gain
        self.offset = offset

    def apply(self, reading: float) -> float:
        import math

        if not math.isfinite(reading):
            raise ValueError("Invalid sensor reading")
        return calibrated(reading * self.gain, self.offset)

    def update(self, gain: float, offset: float, authorized: bool) -> None:
        if not authorized:
            raise PermissionError("Service authorization required")
        proposed = Calibration(gain, offset)
        self.gain, self.offset = proposed.gain, proposed.offset

    def snapshot(self) -> dict:
        return {"gain": self.gain, "offset": self.offset}

import math
from collections import deque


def average(samples: list[float]) -> float:
    if not samples:
        raise ValueError("No samples")
    return sum(samples) / len(samples)


class PressureWindow:
    """Bound retained samples and reject invalid values before changing the window."""

    def __init__(self, size: int):
        if size <= 0:
            raise ValueError("Positive window size required")
        self.samples: deque[float] = deque(maxlen=size)
        self.total_samples = 0

    def append(self, value: float) -> float:
        if not math.isfinite(value) or value < 0:
            raise ValueError("Invalid pressure sample")
        self.samples.append(value)
        self.total_samples += 1
        return average(list(self.samples))

    def reset(self) -> None:
        self.samples.clear()
        self.total_samples = 0

    def snapshot(self) -> dict:
        return {
            "size": self.samples.maxlen,
            "samples": list(self.samples),
            "total_samples": self.total_samples,
        }

import math
from dataclasses import dataclass
from enum import StrEnum

from kestrel.alarm_latch import latched


def occluded(pressure: float, threshold: float = 80.0) -> bool:
    if pressure < 0:
        raise ValueError("Invalid pressure")
    return pressure > threshold


class PressureState(StrEnum):
    SAFE = "safe"
    OCCLUDED = "occluded"
    FAULT = "fault"


@dataclass(frozen=True)
class PressureSample:
    value_kpa: float
    timestamp_s: float


@dataclass(frozen=True)
class PressureDecision:
    state: PressureState
    stop_output: bool
    alarm_required: bool
    reason: str


class PressureMonitor:
    """Validate ordered samples and latch sustained threshold crossings.

    Time is supplied by the bench so boundary trials are deterministic.
    A missing or non-finite sample inhibits output; it never becomes a safe zero.
    """

    def __init__(self, threshold_kpa: float = 80.0, dwell_s: float = 3.0):
        if threshold_kpa <= 0 or dwell_s < 0:
            raise ValueError("Invalid pressure limits")
        self.threshold_kpa = threshold_kpa
        self.dwell_s = dwell_s
        self.last_time = None
        self.crossing_since = None
        self.latched = False

    def evaluate(self, sample: PressureSample | None) -> PressureDecision:
        if sample is None or not math.isfinite(sample.value_kpa):
            return PressureDecision(PressureState.FAULT, True, True, "Missing or invalid sample")
        if sample.value_kpa < 0 or not math.isfinite(sample.timestamp_s):
            return PressureDecision(
                PressureState.FAULT, True, True, "Invalid measured value or time"
            )
        if self.last_time is not None and sample.timestamp_s < self.last_time:
            return PressureDecision(PressureState.FAULT, True, True, "Decreasing sample timestamp")
        self.last_time = sample.timestamp_s
        if occluded(sample.value_kpa, self.threshold_kpa):
            if self.crossing_since is None:
                self.crossing_since = sample.timestamp_s
            if sample.timestamp_s - self.crossing_since >= self.dwell_s:
                self.latched = True
        else:
            self.crossing_since = None
        if self.latched:
            return PressureDecision(PressureState.OCCLUDED, True, True, "Sustained occlusion latch")
        return PressureDecision(PressureState.SAFE, False, False, "Valid sample below dwell limit")

    def acknowledge(self, sample: PressureSample) -> bool:
        if not math.isfinite(sample.value_kpa) or sample.value_kpa < 0:
            return False
        if occluded(sample.value_kpa, self.threshold_kpa):
            return False
        self.latched = False
        self.crossing_since = None
        return True


def pressure_alarm(decision: PressureDecision, active: bool, acknowledged: bool) -> bool:
    """Route a validated pressure decision through the shared alarm latch."""
    return latched(active, acknowledged, decision.alarm_required)

def parse_rate(value: str, maximum: float) -> float:
    rate = float(value)
    if not 0 < rate <= maximum:
        raise ValueError("Invalid rate")
    return rate
